//***********************************************************************
//  Multiplication in GF(p^2), both components (Karatsuba, 3 montmuls)
//  Operation: c0 = a0 x b0 - a1 x b1 ; c1 = a0 x b1 + a1 x b0
//    as P0 = a0 x b0, P1 = a1 x b1, P2 = (a0+a1) x (b0+b1)  (all raw,
//    i.e. without the final masked subtraction of p), then
//    c0 = (P0 + 2p) - P1 and c1 = (fold(P2 + 2p - P0) + 2p) - P1,
//    each folded into [0, 2^669) by masked subtractions of p
//    (2/2/2 passes for e/c0/c1).  The additive Karatsuba sums
//    s = a0+a1, r = b0+b1 are < 2^670, so s x r stays inside the
//    8 x 2^1338 numerator envelope the montmul kernels allow.
//  Inputs: a = [a1, a0] stored in [x1]
//          b = [b1, b0] stored in [x2]
//  Output: c = [c1, c0] stored in [x0]  (written only at the end: c may
//          alias a or b)
//  Register allocation: multiplicand (r/b0/b1 in turn) = x3..x13;
//                       acc z0..z11 = x14..x17,x19..x26,
//                       scalar bi = x27, MULADD temp x28;
//                       scalars (s/a0/a1) streamed from [sp]/[x1].
//  Stack: [sp+0 .. 88) holds s, then P2, then w = fold(P2+2p-P0) + 2p;
//         [sp+88 .. 176) holds u = P0 + 2p.
//***********************************************************************
.global fp2_mul
.p2align 6
fp2_mul:
    sub   sp, sp, #256               // 176 for s/P2/w + u buffer + 80 for callee saves
    stp   x19, x20, [sp, #176]
    stp   x21, x22, [sp, #192]
    stp   x23, x24, [sp, #208]
    stp   x25, x26, [sp, #224]
    stp   x27, x28, [sp, #240]

    // s = a0 + a1 (raw, < 2^670) -> [sp]
    ldp   x14, x15, [x1]
    ldp   x16, x17, [x1, #16]
    ldp   x19, x20, [x1, #32]
    ldp   x21, x22, [x1, #48]
    ldp   x23, x24, [x1, #64]
    ldr   x25, [x1, #80]
    ldp   x27, x28, [x1, #88]
    adds  x14, x14, x27
    adcs  x15, x15, x28
    ldp   x27, x28, [x1, #104]
    adcs  x16, x16, x27
    adcs  x17, x17, x28
    ldp   x27, x28, [x1, #120]
    adcs  x19, x19, x27
    adcs  x20, x20, x28
    ldp   x27, x28, [x1, #136]
    adcs  x21, x21, x27
    adcs  x22, x22, x28
    ldp   x27, x28, [x1, #152]
    adcs  x23, x23, x27
    adcs  x24, x24, x28
    ldr   x27, [x1, #168]
    adc   x25, x25, x27
    stp   x14, x15, [sp]
    stp   x16, x17, [sp, #16]
    stp   x19, x20, [sp, #32]
    stp   x21, x22, [sp, #48]
    stp   x23, x24, [sp, #64]
    str   x25, [sp, #80]
    // r = b0 + b1 (raw) -> x3..x13, resident multiplicand of P2
    ldp   x3, x4, [x2]
    ldp   x5, x6, [x2, #16]
    ldp   x7, x8, [x2, #32]
    ldp   x9, x10, [x2, #48]
    ldp   x11, x12, [x2, #64]
    ldr   x13, [x2, #80]
    ldp   x27, x28, [x2, #88]
    adds  x3, x3, x27
    adcs  x4, x4, x28
    ldp   x27, x28, [x2, #104]
    adcs  x5, x5, x27
    adcs  x6, x6, x28
    ldp   x27, x28, [x2, #120]
    adcs  x7, x7, x27
    adcs  x8, x8, x28
    ldp   x27, x28, [x2, #136]
    adcs  x9, x9, x27
    adcs  x10, x10, x28
    ldp   x27, x28, [x2, #152]
    adcs  x11, x11, x27
    adcs  x12, x12, x28
    ldr   x27, [x2, #168]
    adc   x13, x13, x27

    // [x14:x26] <- z = r x s0
    ldr   x27, [sp]
    MUL64x704  x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x27, x28
    FPMUL704x704  sp, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x27, x28
    // P2 (raw) -> [sp], overwriting s (fully consumed)
    stp   x26, x14, [sp]
    stp   x15, x16, [sp, #16]
    stp   x17, x19, [sp, #32]
    stp   x20, x21, [sp, #48]
    stp   x22, x23, [sp, #64]
    str   x24, [sp, #80]

    // [x26, x14:x25] <- z = b0 x a0_0
    ldp   x3, x4, [x2]
    ldp   x5, x6, [x2, #16]
    ldp   x7, x8, [x2, #32]
    ldp   x9, x10, [x2, #48]
    ldp   x11, x12, [x2, #64]
    ldr   x13, [x2, #80]
    ldr   x27, [x1]
    MUL64x704  x26,x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x27, x28
    FPMUL704x704  x1, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x26,x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25, x27, x28

    // u = P0 + 2p -> [sp+88]  (b0 is dead, reuse x3..x13)
    mov   x28, #-2
    adds  x3, x25, x28
    mov   x28, #-1
    adcs  x4, x26, x28
    adcs  x5, x14, x28
    adcs  x6, x15, x28
    adcs  x7, x16, x28
    adcs  x8, x17, x28
    adcs  x9, x19, x28
    adcs  x10, x20, x28
    adcs  x11, x21, x28
    adcs  x12, x22, x28
    movz  x28, #0xffff
    movk  x28, #0x21ff, lsl #16      // 2p[10]
    adc   x13, x23, x28
    stp   x3, x4, [sp, #88]
    stp   x5, x6, [sp, #104]
    stp   x7, x8, [sp, #120]
    stp   x9, x10, [sp, #136]
    stp   x11, x12, [sp, #152]
    str   x13, [sp, #168]
    // e = P2 + (2p - P0), then fold e into [0, 2^669)
    mov   x28, #-2
    subs  x25, x28, x25
    mov   x28, #-1
    sbcs  x26, x28, x26
    sbcs  x14, x28, x14
    sbcs  x15, x28, x15
    sbcs  x16, x28, x16
    sbcs  x17, x28, x17
    sbcs  x19, x28, x19
    sbcs  x20, x28, x20
    sbcs  x21, x28, x21
    sbcs  x22, x28, x22
    movz  x28, #0xffff
    movk  x28, #0x21ff, lsl #16      // 2p[10]
    sbc   x23, x28, x23
    ldp   x27, x28, [sp]
    adds  x25, x25, x27
    adcs  x26, x26, x28
    ldp   x27, x28, [sp, #16]
    adcs  x14, x14, x27
    adcs  x15, x15, x28
    ldp   x27, x28, [sp, #32]
    adcs  x16, x16, x27
    adcs  x17, x17, x28
    ldp   x27, x28, [sp, #48]
    adcs  x19, x19, x27
    adcs  x20, x20, x28
    ldp   x27, x28, [sp, #64]
    adcs  x21, x21, x27
    adcs  x22, x22, x28
    ldr   x27, [sp, #80]
    adc   x23, x23, x27
    movz  x3, #0xffff
    movk  x3, #0x10ff, lsl #16       // p[10]
    // e pass 1/2
    lsr   x27, x23, #29
    neg   x27, x27
    asr   x27, x27, #63
    and   x28, x3, x27
    subs  x25, x25, x27
    sbcs  x26, x26, x27
    sbcs  x14, x14, x27
    sbcs  x15, x15, x27
    sbcs  x16, x16, x27
    sbcs  x17, x17, x27
    sbcs  x19, x19, x27
    sbcs  x20, x20, x27
    sbcs  x21, x21, x27
    sbcs  x22, x22, x27
    sbc   x23, x23, x28
    // e pass 2/2
    lsr   x27, x23, #29
    neg   x27, x27
    asr   x27, x27, #63
    and   x28, x3, x27
    subs  x25, x25, x27
    sbcs  x26, x26, x27
    sbcs  x14, x14, x27
    sbcs  x15, x15, x27
    sbcs  x16, x16, x27
    sbcs  x17, x17, x27
    sbcs  x19, x19, x27
    sbcs  x20, x20, x27
    sbcs  x21, x21, x27
    sbcs  x22, x22, x27
    sbc   x23, x23, x28
    // w = e + 2p -> [sp], overwriting P2 (fully consumed)
    mov   x28, #-2
    adds  x25, x25, x28
    mov   x28, #-1
    adcs  x26, x26, x28
    adcs  x14, x14, x28
    adcs  x15, x15, x28
    adcs  x16, x16, x28
    adcs  x17, x17, x28
    adcs  x19, x19, x28
    adcs  x20, x20, x28
    adcs  x21, x21, x28
    adcs  x22, x22, x28
    movz  x28, #0xffff
    movk  x28, #0x21ff, lsl #16      // 2p[10]
    adc   x23, x23, x28
    stp   x25, x26, [sp]
    stp   x14, x15, [sp, #16]
    stp   x16, x17, [sp, #32]
    stp   x19, x20, [sp, #48]
    stp   x21, x22, [sp, #64]
    str   x23, [sp, #80]

    // [x25:x26, x14:x24] <- z = b1 x a1_0
    ldp   x3, x4, [x2, #88]
    ldp   x5, x6, [x2, #104]
    ldp   x7, x8, [x2, #120]
    ldp   x9, x10, [x2, #136]
    ldp   x11, x12, [x2, #152]
    ldr   x13, [x2, #168]
    add   x1, x1, #88                // a1; x1 is dead after P1
    ldr   x27, [x1]
    MUL64x704  x25,x26,x14,x15,x16,x17,x19,x20,x21,x22,x23,x24, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x27, x28
    FPMUL704x704  x1, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x25,x26,x14,x15,x16,x17,x19,x20,x21,x22,x23,x24, x27, x28

    // c0 = u - P1 -> x3..x13 ; c1 = w - P1 -> x24..x26,x14..x17,x19..x22 (in place)
    ldp   x27, x28, [sp, #88]
    subs  x3, x27, x24
    sbcs  x4, x28, x25
    ldp   x27, x28, [sp, #104]
    sbcs  x5, x27, x26
    sbcs  x6, x28, x14
    ldp   x27, x28, [sp, #120]
    sbcs  x7, x27, x15
    sbcs  x8, x28, x16
    ldp   x27, x28, [sp, #136]
    sbcs  x9, x27, x17
    sbcs  x10, x28, x19
    ldp   x27, x28, [sp, #152]
    sbcs  x11, x27, x20
    sbcs  x12, x28, x21
    ldr   x27, [sp, #168]
    sbc   x13, x27, x22
    ldp   x27, x28, [sp]
    subs  x24, x27, x24
    sbcs  x25, x28, x25
    ldp   x27, x28, [sp, #16]
    sbcs  x26, x27, x26
    sbcs  x14, x28, x14
    ldp   x27, x28, [sp, #32]
    sbcs  x15, x27, x15
    sbcs  x16, x28, x16
    ldp   x27, x28, [sp, #48]
    sbcs  x17, x27, x17
    sbcs  x19, x28, x19
    ldp   x27, x28, [sp, #64]
    sbcs  x20, x27, x20
    sbcs  x21, x28, x21
    ldr   x27, [sp, #80]
    sbc   x22, x27, x22
    movz  x23, #0xffff
    movk  x23, #0x10ff, lsl #16      // p[10]
    // c0 pass 1/2
    lsr   x27, x13, #29
    neg   x27, x27
    asr   x27, x27, #63
    and   x28, x23, x27
    subs  x3, x3, x27
    sbcs  x4, x4, x27
    sbcs  x5, x5, x27
    sbcs  x6, x6, x27
    sbcs  x7, x7, x27
    sbcs  x8, x8, x27
    sbcs  x9, x9, x27
    sbcs  x10, x10, x27
    sbcs  x11, x11, x27
    sbcs  x12, x12, x27
    sbc   x13, x13, x28
    // c0 pass 2/2
    lsr   x27, x13, #29
    neg   x27, x27
    asr   x27, x27, #63
    and   x28, x23, x27
    subs  x3, x3, x27
    sbcs  x4, x4, x27
    sbcs  x5, x5, x27
    sbcs  x6, x6, x27
    sbcs  x7, x7, x27
    sbcs  x8, x8, x27
    sbcs  x9, x9, x27
    sbcs  x10, x10, x27
    sbcs  x11, x11, x27
    sbcs  x12, x12, x27
    sbc   x13, x13, x28
    // c1 pass 1/2
    lsr   x27, x22, #29
    neg   x27, x27
    asr   x27, x27, #63
    and   x28, x23, x27
    subs  x24, x24, x27
    sbcs  x25, x25, x27
    sbcs  x26, x26, x27
    sbcs  x14, x14, x27
    sbcs  x15, x15, x27
    sbcs  x16, x16, x27
    sbcs  x17, x17, x27
    sbcs  x19, x19, x27
    sbcs  x20, x20, x27
    sbcs  x21, x21, x27
    sbc   x22, x22, x28
    // c1 pass 2/2
    lsr   x27, x22, #29
    neg   x27, x27
    asr   x27, x27, #63
    and   x28, x23, x27
    subs  x24, x24, x27
    sbcs  x25, x25, x27
    sbcs  x26, x26, x27
    sbcs  x14, x14, x27
    sbcs  x15, x15, x27
    sbcs  x16, x16, x27
    sbcs  x17, x17, x27
    sbcs  x19, x19, x27
    sbcs  x20, x20, x27
    sbcs  x21, x21, x27
    sbc   x22, x22, x28

    stp   x3, x4, [x0]
    stp   x5, x6, [x0, #16]
    stp   x7, x8, [x0, #32]
    stp   x9, x10, [x0, #48]
    stp   x11, x12, [x0, #64]
    str   x13, [x0, #80]
    stp   x24, x25, [x0, #88]
    stp   x26, x14, [x0, #104]
    stp   x15, x16, [x0, #120]
    stp   x17, x19, [x0, #136]
    stp   x20, x21, [x0, #152]
    str   x22, [x0, #168]
    ldp   x27, x28, [sp, #240]
    ldp   x25, x26, [sp, #224]
    ldp   x23, x24, [sp, #208]
    ldp   x21, x22, [sp, #192]
    ldp   x19, x20, [sp, #176]
    add   sp, sp, #256
    ret

//***********************************************************************
//  Squaring in GF(p^2), both components
//  Operation: c0 = (a0+a1) x (a0-a1) ; c1 = 2 a0 x a1
//  Inputs: a = [a1, a0] stored in [x1]
//  Output: c = [c1, c0] stored in [x0]  (c may alias a)
//  Register allocation: multiplicand (d = a0-a1+2p, then a1) = x3..x13;
//                       acc z0..z11 = x14..x17,x19..x26,
//                       scalar bi = x27, MULADD temp x28;
//                       scalars streamed from [sp].
//  Stack: [sp+0 .. 88) holds s = a0+a1 (raw);
//         [sp+88 .. 176) holds t = 2*a0 (raw; self-add, EXTR is slow).
//***********************************************************************
.global fp2_sqr
.p2align 6
fp2_sqr:
    sub   sp, sp, #256               // 176 for s + t buffer + 80 for callee saves
    stp   x19, x20, [sp, #176]
    stp   x21, x22, [sp, #192]
    stp   x23, x24, [sp, #208]
    stp   x25, x26, [sp, #224]
    stp   x27, x28, [sp, #240]

    // t = 2*a0 (raw) -> [sp+88] ; a0 stays in x3..x13
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    ldp   x9, x10, [x1, #48]
    ldp   x11, x12, [x1, #64]
    ldr   x13, [x1, #80]
    adds  x14, x3, x3
    adcs  x15, x4, x4
    adcs  x16, x5, x5
    adcs  x17, x6, x6
    adcs  x19, x7, x7
    adcs  x20, x8, x8
    adcs  x21, x9, x9
    adcs  x22, x10, x10
    adcs  x23, x11, x11
    adcs  x24, x12, x12
    adc   x25, x13, x13
    stp   x14, x15, [sp, #88]
    stp   x16, x17, [sp, #104]
    stp   x19, x20, [sp, #120]
    stp   x21, x22, [sp, #136]
    stp   x23, x24, [sp, #152]
    str   x25, [sp, #168]
    // s = a0 + a1 (raw) -> [sp]
    ldp   x14, x15, [x1, #88]
    ldp   x16, x17, [x1, #104]
    ldp   x19, x20, [x1, #120]
    ldp   x21, x22, [x1, #136]
    ldp   x23, x24, [x1, #152]
    ldr   x25, [x1, #168]
    adds  x14, x14, x3
    adcs  x15, x4, x15
    adcs  x16, x5, x16
    adcs  x17, x6, x17
    adcs  x19, x7, x19
    adcs  x20, x8, x20
    adcs  x21, x9, x21
    adcs  x22, x10, x22
    adcs  x23, x11, x23
    adcs  x24, x12, x24
    adc   x25, x25, x13
    stp   x14, x15, [sp]
    stp   x16, x17, [sp, #16]
    stp   x19, x20, [sp, #32]
    stp   x21, x22, [sp, #48]
    stp   x23, x24, [sp, #64]
    str   x25, [sp, #80]
    // d = a0 - a1 + 2p (raw) -> x3..x13 ; p2 = 2p = {-2,-1,...,0x0000000021FFFFFF}
    ldp   x14, x15, [x1, #88]
    subs  x3, x3, x14
    sbcs  x4, x4, x15
    ldp   x14, x15, [x1, #104]
    sbcs  x5, x5, x14
    sbcs  x6, x6, x15
    ldp   x14, x15, [x1, #120]
    sbcs  x7, x7, x14
    sbcs  x8, x8, x15
    ldp   x14, x15, [x1, #136]
    sbcs  x9, x9, x14
    sbcs  x10, x10, x15
    ldp   x14, x15, [x1, #152]
    sbcs  x11, x11, x14
    sbcs  x12, x12, x15
    ldr   x14, [x1, #168]
    sbcs  x13, x13, x14
    mov   x14, #-2
    adds  x3, x3, x14
    mov   x14, #-1
    adcs  x4, x4, x14
    adcs  x5, x5, x14
    adcs  x6, x6, x14
    adcs  x7, x7, x14
    adcs  x8, x8, x14
    adcs  x9, x9, x14
    adcs  x10, x10, x14
    adcs  x11, x11, x14
    adcs  x12, x12, x14
    movz  x14, #0xffff
    movk  x14, #0x21ff, lsl #16      // 2p[10]
    adc   x13, x13, x14

    // [x14:x26] <- z = d x s0
    ldr   x27, [sp]
    MUL64x704  x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x27, x28
    FPMUL704x704  sp, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x27, x28

    // c0 -> [x0] (a0's slot; a1 is still intact if c == a)
    stp   x26, x14, [x0]
    stp   x15, x16, [x0, #16]
    stp   x17, x19, [x0, #32]
    stp   x20, x21, [x0, #48]
    stp   x22, x23, [x0, #64]
    str   x24, [x0, #80]

    // [x26, x14:x25] <- z = a1 x t0
    ldp   x3, x4, [x1, #88]
    ldp   x5, x6, [x1, #104]
    ldp   x7, x8, [x1, #120]
    ldp   x9, x10, [x1, #136]
    ldp   x11, x12, [x1, #152]
    ldr   x13, [x1, #168]
    add   x1, sp, #88                // x1 is dead after the a1 load: reuse it as the t pointer
    ldr   x27, [x1]
    MUL64x704  x26,x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x27, x28
    FPMUL704x704  x1, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x26,x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25, x27, x28

    stp   x25, x26, [x0, #88]
    stp   x14, x15, [x0, #104]
    stp   x16, x17, [x0, #120]
    stp   x19, x20, [x0, #136]
    stp   x21, x22, [x0, #152]
    str   x23, [x0, #168]
    ldp   x27, x28, [sp, #240]
    ldp   x25, x26, [sp, #224]
    ldp   x23, x24, [sp, #208]
    ldp   x21, x22, [sp, #192]
    ldp   x19, x20, [sp, #176]
    add   sp, sp, #256
    ret

//***********************************************************************
//  Field multiplication in GF(p)
//  Operation: c = a x b mod p
//  Inputs: a stored in [x1], b stored in [x2]
//  Output: c stored in [x0]
//  Register allocation: a (resident) = x3..x13;
//                       acc z0..z11 = x14..x17,x19..x26,
//                       scalar bi = x27, MULADD temp x28;
//                       the reduction borrows bi (dead there).
//***********************************************************************
.global fp_mul
.p2align 6
fp_mul:
    stp   x19, x20, [sp, #-80]!
    stp   x21, x22, [sp, #16]
    stp   x23, x24, [sp, #32]
    stp   x25, x26, [sp, #48]
    stp   x27, x28, [sp, #64]
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    ldp   x9, x10, [x1, #48]
    ldp   x11, x12, [x1, #64]
    ldr   x13, [x1, #80]

    // [x14:x26] <- z = a x b0
    ldr   x27, [x2]
    MUL64x704  x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x27, x28
    FPMUL704x704  x2, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x27, x28

    stp   x26, x14, [x0]
    stp   x15, x16, [x0, #16]
    stp   x17, x19, [x0, #32]
    stp   x20, x21, [x0, #48]
    stp   x22, x23, [x0, #64]
    str   x24, [x0, #80]
    ldp   x27, x28, [sp, #64]
    ldp   x25, x26, [sp, #48]
    ldp   x23, x24, [sp, #32]
    ldp   x21, x22, [sp, #16]
    ldp   x19, x20, [sp], #80
    ret

.global fp_sqr
.p2align 6
fp_sqr:
    mov   x2, x1
    b     fp_mul
